//! sourcegull-monitoring: Sourcegull's dashboards and alerts, defined in Rust and generated into Grafana
//! dashboard JSON, Prometheus alerting rules and Markdown docs.
//!
//! A [`Dashboard`] per service holds [`Group`]s of rows of [`Observable`]s; an observable is one
//! Prometheus query shown as a panel, optionally with warning and critical [`Threshold`]s that
//! become alerts, an [`Owner`] and next steps for whoever is paged. The definitions are in
//! [`definitions`]; [`Output::render`] produces every generated file.
//!
//! Queries only use metrics Sourcegull exports (the names in [`sourcegull_types::metric_names`], which
//! the recording code uses too) plus Prometheus's own `up`; `tests/generated.rs` checks both,
//! and that the checked-in files are current.

pub mod definitions;
mod docs;
mod grafana;
mod prometheus;

use std::fmt::Write as _;

/// Where the generated alert docs are published; alerts link here (`runbook_url`).
pub const ALERTS_DOC_URL: &str =
    "https://github.com/sourcegull/sourcegull/blob/main/docs/observability/alerts.md";

/// Header of every generated file (in its own comment syntax).
pub const GENERATED_NOTICE: &str = "Generated by `sourcegull monitoring generate` from \
     crates/monitoring. Do not edit; change the definitions and regenerate.";

/// A dashboard of one service (a role, the executors or Postgres).
#[derive(Debug, Clone)]
pub struct Dashboard {
    /// Short name: the Grafana uid suffix, the `service` label of its alerts and the prefix of
    /// their names (`web`, `repo`, …).
    pub name: &'static str,
    /// Title shown in Grafana and the docs.
    pub title: &'static str,
    /// What the service does and what the dashboard covers.
    pub description: &'static str,
    /// Panel groups, shown as Grafana rows.
    pub groups: Vec<Group>,
}

/// A titled group of panel rows.
#[derive(Debug, Clone)]
pub struct Group {
    pub title: &'static str,
    /// Collapsed by default (details most people do not need).
    pub hidden: bool,
    pub rows: Vec<Vec<Observable>>,
}

impl Group {
    /// An expanded group.
    pub fn new(title: &'static str, rows: Vec<Vec<Observable>>) -> Self {
        Self {
            title,
            hidden: false,
            rows,
        }
    }

    /// A group collapsed by default.
    pub fn hidden(title: &'static str, rows: Vec<Vec<Observable>>) -> Self {
        Self {
            title,
            hidden: true,
            rows,
        }
    }
}

/// Team responsible for an observable and its alerts.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Owner {
    /// Search, the text index and streaming results.
    Search,
    /// Repositories: code host syncs, clones, fetches, repo nodes.
    Source,
    /// Code navigation, SCIP uploads, auto-indexing.
    CodeIntel,
    /// Bulk changes.
    Batches,
    /// Watches and Trends.
    CodeInsights,
    /// The platform: web servers, workers, executors, blob store, Postgres.
    Platform,
}

impl Owner {
    /// The `owner` label value.
    pub fn as_str(self) -> &'static str {
        match self {
            Owner::Search => "search",
            Owner::Source => "source",
            Owner::CodeIntel => "code-intel",
            Owner::Batches => "batches",
            Owner::CodeInsights => "code-insights",
            Owner::Platform => "platform",
        }
    }
}

/// Unit of an observable's values.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Unit {
    /// A plain number.
    Number,
    /// Events per second.
    PerSecond,
    /// Seconds.
    Seconds,
    /// Bytes.
    Bytes,
    /// Bytes per second.
    BytesPerSecond,
    /// A ratio in [0, 1], shown as a percentage.
    Ratio,
}

impl Unit {
    /// The Grafana unit id.
    fn grafana(self) -> &'static str {
        match self {
            Unit::Number => "short",
            Unit::PerSecond => "ops",
            Unit::Seconds => "s",
            Unit::Bytes => "bytes",
            Unit::BytesPerSecond => "Bps",
            Unit::Ratio => "percentunit",
        }
    }

    /// `value` for people, e.g. `5%`, `30s`, `10 GiB`.
    pub fn format(self, value: f64) -> String {
        match self {
            Unit::Ratio => format!("{}%", trim_float(value * 100.0)),
            Unit::Seconds => format_duration(value),
            Unit::Bytes => format_bytes(value),
            Unit::BytesPerSecond => format!("{}/s", format_bytes(value)),
            Unit::PerSecond => format!("{}/s", trim_float(value)),
            Unit::Number => trim_float(value),
        }
    }
}

fn trim_float(v: f64) -> String {
    let s = format!("{v:.3}");
    s.trim_end_matches('0').trim_end_matches('.').to_owned()
}

fn format_bytes(v: f64) -> String {
    const UNITS: &[&str] = &["B", "KiB", "MiB", "GiB", "TiB"];
    let mut v = v;
    let mut i = 0;
    while v >= 1024.0 && i + 1 < UNITS.len() {
        v /= 1024.0;
        i += 1;
    }
    format!("{} {}", trim_float(v), UNITS[i])
}

/// `90` → `1m30s`, `3600` → `1h`.
fn format_duration(secs: f64) -> String {
    if secs.fract() != 0.0 || secs < 60.0 {
        return format!("{}s", trim_float(secs));
    }
    let secs = secs as u64;
    let (h, m, s) = (secs / 3600, secs % 3600 / 60, secs % 60);
    let mut out = String::new();
    if h > 0 {
        let _ = write!(out, "{h}h");
    }
    if m > 0 {
        let _ = write!(out, "{m}m");
    }
    if s > 0 {
        let _ = write!(out, "{s}s");
    }
    out
}

/// Direction of a threshold.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Comparison {
    /// Fires when the value is above the threshold.
    Above,
    /// Fires when the value is below the threshold.
    Below,
}

/// An alert threshold: fires when the query's value stays beyond `value` for `for_secs`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Threshold {
    pub comparison: Comparison,
    pub value: f64,
    pub for_secs: u32,
}

impl Threshold {
    /// Fires when the value stays above `value`.
    pub const fn above(value: f64) -> Self {
        Self {
            comparison: Comparison::Above,
            value,
            for_secs: 0,
        }
    }

    /// Fires when the value stays below `value`.
    pub const fn below(value: f64) -> Self {
        Self {
            comparison: Comparison::Below,
            value,
            for_secs: 0,
        }
    }

    /// For at least `minutes` minutes.
    pub const fn for_minutes(mut self, minutes: u32) -> Self {
        self.for_secs = minutes * 60;
        self
    }

    fn operator(&self) -> &'static str {
        match self.comparison {
            Comparison::Above => ">",
            Comparison::Below => "<",
        }
    }

    /// `above 5% for 10m`.
    fn describe(&self, unit: Unit) -> String {
        let dir = match self.comparison {
            Comparison::Above => "above",
            Comparison::Below => "below",
        };
        let mut s = format!("{dir} {}", unit.format(self.value));
        if self.for_secs > 0 {
            let _ = write!(s, " for {}", format_duration(f64::from(self.for_secs)));
        }
        s
    }
}

/// Alert severity.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Severity {
    /// Something needs a look soon; users may not notice yet.
    Warning,
    /// Users are affected or will be shortly; act now.
    Critical,
}

impl Severity {
    /// The `severity` label value.
    pub fn as_str(self) -> &'static str {
        match self {
            Severity::Warning => "warning",
            Severity::Critical => "critical",
        }
    }
}

/// One Prometheus query shown as a panel, optionally alerting.
#[derive(Debug, Clone)]
pub struct Observable {
    /// Unique within its dashboard, `snake_case`. The alert name is `<dashboard>_<name>`.
    pub name: &'static str,
    /// What the value is, lowercase, e.g. `share of requests answered with 5xx`. The panel
    /// title and the alert summary.
    pub description: &'static str,
    /// The PromQL query.
    pub query: String,
    /// Grafana legend, e.g. `{{route}}`.
    pub legend: &'static str,
    pub unit: Unit,
    pub warning: Option<Threshold>,
    pub critical: Option<Threshold>,
    pub owner: Owner,
    /// How to read the panel (dashboards.md and the panel description).
    pub interpretation: &'static str,
    /// What to do when it alerts (alerts.md), one item per bullet.
    pub next_steps: &'static [&'static str],
}

impl Observable {
    /// A panel without alerts, owned by `owner`.
    pub fn new(
        name: &'static str,
        description: &'static str,
        query: impl Into<String>,
        owner: Owner,
    ) -> Self {
        Self {
            name,
            description,
            query: query.into(),
            legend: "",
            unit: Unit::Number,
            warning: None,
            critical: None,
            owner,
            interpretation: "",
            next_steps: &[],
        }
    }

    pub fn legend(mut self, legend: &'static str) -> Self {
        self.legend = legend;
        self
    }

    pub fn unit(mut self, unit: Unit) -> Self {
        self.unit = unit;
        self
    }

    pub fn warning(mut self, t: Threshold) -> Self {
        self.warning = Some(t);
        self
    }

    pub fn critical(mut self, t: Threshold) -> Self {
        self.critical = Some(t);
        self
    }

    pub fn interpretation(mut self, text: &'static str) -> Self {
        self.interpretation = text;
        self
    }

    pub fn next_steps(mut self, steps: &'static [&'static str]) -> Self {
        self.next_steps = steps;
        self
    }

    /// The thresholds that alert, warning first.
    pub fn alerts(&self) -> impl Iterator<Item = (Severity, Threshold)> + '_ {
        [
            self.warning.map(|t| (Severity::Warning, t)),
            self.critical.map(|t| (Severity::Critical, t)),
        ]
        .into_iter()
        .flatten()
    }

    /// Whether the observable has any alert.
    pub fn alerting(&self) -> bool {
        self.warning.is_some() || self.critical.is_some()
    }
}

/// `<dashboard>_<observable>`: the Prometheus alert name and the docs anchor.
pub fn alert_name(dashboard: &Dashboard, o: &Observable) -> String {
    format!("{}_{}", dashboard.name, o.name)
}

/// One-line alert description, e.g. `web: share of requests answered with 5xx above 5% for 5m`.
pub fn alert_description(dashboard: &Dashboard, o: &Observable, t: &Threshold) -> String {
    format!(
        "{}: {} {}",
        dashboard.name,
        o.description,
        t.describe(o.unit)
    )
}

/// Checks the definitions: unique names, alerts with next steps, sane thresholds.
pub fn validate(dashboards: &[Dashboard]) -> Result<(), Vec<String>> {
    let mut errors = Vec::new();
    let mut dashboard_names = std::collections::HashSet::new();
    for d in dashboards {
        if !dashboard_names.insert(d.name) {
            errors.push(format!("dashboard {}: duplicate name", d.name));
        }
        let mut names = std::collections::HashSet::new();
        for o in d.groups.iter().flat_map(|g| g.rows.iter().flatten()) {
            let id = format!("{}/{}", d.name, o.name);
            if !names.insert(o.name) {
                errors.push(format!("{id}: duplicate observable name"));
            }
            if !o
                .name
                .chars()
                .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
            {
                errors.push(format!("{id}: name must be snake_case"));
            }
            if o.description.is_empty() || o.query.trim().is_empty() {
                errors.push(format!("{id}: description and query are required"));
            }
            if o.alerting() && o.next_steps.is_empty() {
                errors.push(format!("{id}: alerts need next steps"));
            }
            if !o.alerting() && o.interpretation.is_empty() {
                errors.push(format!(
                    "{id}: panels without alerts need an interpretation"
                ));
            }
            if let (Some(w), Some(c)) = (o.warning, o.critical) {
                let ordered = match (w.comparison, c.comparison) {
                    (Comparison::Above, Comparison::Above) => w.value <= c.value,
                    (Comparison::Below, Comparison::Below) => w.value >= c.value,
                    _ => false,
                };
                if !ordered {
                    errors.push(format!(
                        "{id}: the critical threshold must be beyond the warning one"
                    ));
                }
            }
        }
        for g in &d.groups {
            for row in &g.rows {
                if row.is_empty() || row.len() > 4 {
                    errors.push(format!("{}/{}: rows hold 1 to 4 panels", d.name, g.title));
                }
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(errors)
    }
}

/// The generated files, as paths relative to an output directory and their contents.
#[derive(Debug, Clone)]
pub struct Output {
    pub files: Vec<(String, String)>,
}

/// Repository directories holding generated dashboards.
const REPO_DASHBOARD_DIRS: &[&str] = &[
    "deploy/docker/grafana/dashboards",
    "deploy/helm/sourcegull/files/monitoring/dashboards",
];

/// Generated Prometheus rules file name.
pub const RULES_FILE: &str = "sourcegull-alerts.yml";

impl Output {
    /// Renders the dashboards, rules and docs of `dashboards` into the layout
    /// `grafana/sourcegull-<name>.json`, `prometheus/sourcegull-alerts.yml`, `alerts.md` and
    /// `dashboards.md`.
    pub fn render(dashboards: &[Dashboard]) -> Self {
        let mut files = Vec::new();
        for d in dashboards {
            files.push((
                format!("grafana/{}", grafana::file_name(d)),
                grafana::render(d),
            ));
        }
        files.push((
            format!("prometheus/{RULES_FILE}"),
            prometheus::render(dashboards),
        ));
        files.push(("alerts.md".to_owned(), docs::alerts(dashboards)));
        files.push(("dashboards.md".to_owned(), docs::dashboards(dashboards)));
        Self { files }
    }

    /// Writes the files below `dir`, creating directories as needed.
    pub fn write(&self, dir: &std::path::Path) -> std::io::Result<()> {
        for (path, content) in &self.files {
            let path = dir.join(path);
            if let Some(parent) = path.parent() {
                std::fs::create_dir_all(parent)?;
            }
            std::fs::write(path, content)?;
        }
        Ok(())
    }

    /// Writes the files to their places in the repository at `root` (see [`Output::repo_paths`])
    /// and removes dashboards that are no longer generated.
    pub fn write_repo(&self, root: &std::path::Path) -> std::io::Result<()> {
        for extra in self.unexpected_repo_files(root) {
            std::fs::remove_file(root.join(extra))?;
        }
        for (path, content) in &self.files {
            for repo_path in Self::repo_paths(path) {
                let path = root.join(repo_path);
                if let Some(parent) = path.parent() {
                    std::fs::create_dir_all(parent)?;
                }
                std::fs::write(path, content)?;
            }
        }
        Ok(())
    }

    /// Dashboard files (`sourcegull-*.json`) in the repository's dashboard directories that this
    /// output does not generate.
    pub fn unexpected_repo_files(&self, root: &std::path::Path) -> Vec<String> {
        let expected: std::collections::HashSet<String> = self
            .files
            .iter()
            .flat_map(|(path, _)| Self::repo_paths(path))
            .collect();
        let mut extra = Vec::new();
        for dir in REPO_DASHBOARD_DIRS {
            let Ok(entries) = std::fs::read_dir(root.join(dir)) else {
                continue;
            };
            for entry in entries.flatten() {
                let name = entry.file_name().to_string_lossy().into_owned();
                let path = format!("{dir}/{name}");
                if name.starts_with("sourcegull-")
                    && name.ends_with(".json")
                    && !expected.contains(&path)
                {
                    extra.push(path);
                }
            }
        }
        extra.sort();
        extra
    }

    /// Where each file lives in the repository (some in more than one place: the Compose
    /// files and the Helm chart each carry their own copy).
    pub fn repo_paths(path: &str) -> Vec<String> {
        if let Some(name) = path.strip_prefix("grafana/") {
            vec![
                format!("deploy/docker/grafana/dashboards/{name}"),
                format!("deploy/helm/sourcegull/files/monitoring/dashboards/{name}"),
            ]
        } else if let Some(name) = path.strip_prefix("prometheus/") {
            vec![
                format!("deploy/docker/prometheus/{name}"),
                format!("deploy/helm/sourcegull/files/monitoring/{name}"),
            ]
        } else {
            vec![format!("docs/observability/{path}")]
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn definitions_are_valid() {
        if let Err(errors) = validate(&definitions::dashboards()) {
            panic!("invalid definitions:\n{}", errors.join("\n"));
        }
    }

    #[test]
    fn validate_catches_mistakes() {
        let o = Observable::new("Bad Name", "x", "up", Owner::Platform)
            .warning(Threshold::above(10.0))
            .critical(Threshold::above(5.0));
        let d = Dashboard {
            name: "t",
            title: "T",
            description: "",
            groups: vec![Group::new("g", vec![vec![o.clone(), o]])],
        };
        let errors = validate(&[d]).expect_err("invalid");
        let all = errors.join("\n");
        assert!(all.contains("duplicate observable"), "{all}");
        assert!(all.contains("snake_case"), "{all}");
        assert!(all.contains("next steps"), "{all}");
        assert!(all.contains("critical threshold"), "{all}");
    }

    #[test]
    fn formats_values() {
        assert_eq!(Unit::Ratio.format(0.05), "5%");
        assert_eq!(Unit::Ratio.format(0.125), "12.5%");
        assert_eq!(Unit::Seconds.format(30.0), "30s");
        assert_eq!(Unit::Seconds.format(5400.0), "1h30m");
        assert_eq!(Unit::Seconds.format(0.5), "0.5s");
        assert_eq!(
            Unit::Bytes.format(10.0 * 1024.0 * 1024.0 * 1024.0),
            "10 GiB"
        );
        assert_eq!(Unit::Number.format(1000.0), "1000");
        assert_eq!(
            Threshold::above(0.05).for_minutes(10).describe(Unit::Ratio),
            "above 5% for 10m"
        );
        assert_eq!(Threshold::below(1.0).describe(Unit::Number), "below 1");
    }

    #[test]
    fn every_dashboard_has_alerts_and_unique_alert_names() {
        let dashboards = definitions::dashboards();
        let mut names = std::collections::HashSet::new();
        for d in &dashboards {
            let alerting: Vec<_> = d
                .groups
                .iter()
                .flat_map(|g| g.rows.iter().flatten())
                .filter(|o| o.alerting())
                .collect();
            assert!(!alerting.is_empty(), "{} has no alerts", d.name);
            for o in alerting {
                assert!(names.insert(alert_name(d, o)), "duplicate alert {}", o.name);
            }
        }
    }
}
